import unittest
from candidate import modp

class TestModp(unittest.TestCase):
    def test_modp_positive_integers(self):
        self.assertEqual(modp(3, 5), 3)
        self.assertEqual(modp(1101, 101), 2)

    def test_modp_zero(self):
        self.assertEqual(modp(0, 101), 1)

    def test_modp_negative_integers(self):
        self.assertEqual(modp(-3, 5), 3)

    def test_modp_large_integer(self):
        self.assertEqual(modp(2**64, 101), 64)

    def test_modp_large_input(self):
        self.assertEqual(modp(10**8, 101), 1)

    def test_modp_p_greater_than_2(self):
        self.assertEqual(modp(3, 11), 8)

    def test_modp_p_equals_2(self):
        self.assertEqual(modp(0, 2), 0)
        self.assertEqual(modp(1, 2), 1)

    def test_modp_invalid_input_types(self):
        self.assertRaises(TypeError, modp, 3.5, 5)
        self.assertRaises(TypeError, modp, "3", 5)
        self.assertRaises(TypeError, modp, 3, 3.5)
